def merge_dicts(d1: dict, d2: dict) -> dict:
    """Merge two dictionaries, with d2 overwriting d1."""
    return {**d1, **d2}

print(merge_dicts({'a': 1, 'b': 2}, {'b': 3, 'c': 4}))
